void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
template<class F>void rejects(F f){bool denied=false;try{f();}catch(const std::exception&){denied=true;}check(denied,"invalid identity/write should be rejected");}
QPushButton* button(QWidget* page,const QString& name){for(auto b:page->findChildren<QPushButton*>())if(b->text()==name)return b;throw std::runtime_error("button absent");}
