int main(int argc,char** argv){QApplication app(argc,argv);QCoreApplication::setOrganizationName("NativeCommentTests");QCoreApplication::setApplicationName("CommentWorkshopChecks");try{
  const auto input=QJsonDocument(fixture()).toJson();const auto row=commentWorkshop::normalize(input)[0].toObject();
  check(commentWorkshop::comments(row,{},"creator").size()==2&&!row["coverage"].toObject()["complete"].toBool()&&row["comments"].toArray()[0].toObject()["likes"].isNull(),"creator proof/partial coverage/unknown likes");
  check(commentWorkshop::comments(row,"作者原文","all")[0].toObject()["parentText"].toString().contains("完整尾部"),"full parent quote");check(commentWorkshop::comments(row,"平台标注","all")[0].toObject()["parentMissing"].toBool(),"missing parent flag");
  const auto ref=commentWorkshop::commentRef(row,"reply");check(commentWorkshop::exactComment(ref,QJsonArray{row})==row,"exact comment reference");auto changed=row;auto comments=changed["comments"].toArray();auto modified=comments[1].toObject();modified["text"]="changed";comments[1]=modified;changed["comments"]=comments;rejects([&]{commentWorkshop::exactComment(ref,QJsonArray{changed});});
  auto fake=row;comments=fake["comments"].toArray();modified=comments[2].toObject();modified["creatorStatus"]="verified";comments[2]=modified;fake["comments"]=comments;rejects([&]{commentWorkshop::normalize(QJsonDocument(QJsonObject{{"schema","comment-workshop-v1"},{"records",QJsonArray{fake}}}).toJson());});
  if(argc>1){QFile file(QString::fromLocal8Bit(argv[1]));check(file.open(QIODevice::ReadOnly),"cross-end fixture unreadable");const auto java=QJsonDocument::fromJson(file.readAll()).object();check(java==row,"Java/Qt full normalized payload and composite snapshot identity differ");}
  QTemporaryDir dir;auto business=std::make_shared<BusinessStore>(dir.filePath("business.sqlite"));auto source=business->save("collections",{{"title","原稿"},{"text",row["content"]},{"sourceUrl",row["sourceUrl"]},{"status","imported"}});const auto before=business->read("collections");const auto binding=commentWorkshop::bindSource(row,before,{});check(sourceAnalysis::exactSource(binding,before)==source,"exact local source binding");rejects([&]{commentWorkshop::bindSource(row,QJsonArray{source,source},{});});auto restored=source;restored["executionRevision"]="restored";rejects([&]{sourceAnalysis::exactSource(binding,QJsonArray{restored});});
  CommentWorkshopStore store(business->filePath()+".comment-workshop.sqlite");auto preview=store.preview(input);check(store.list("observations").isEmpty(),"preview wrote before confirmation");auto staged=store.put({{"kind","previews"},{"id","import-preview"},{"preview",preview}});check(store.list("observations").isEmpty(),"preview draft must not approve evidence");check(store.merge(preview,staged["recordRevision"].toString())["added"].toInt()==1&&store.merge(preview)["duplicate"].toInt()==1,"atomic idempotent import");check(store.get("previews","import-preview")["preview"].toObject().isEmpty(),"merge didn't atomically consume preview");
  auto label=store.put({{"kind","labels"},{"id",commentWorkshop::labelId(row["id"].toString(),"parent")},{"label","support"},{"sourceRef",commentWorkshop::commentRef(row,"parent")}});rejects([&]{auto edit=label;edit["label"]="counter";store.put(edit);});check(store.labels(row["id"].toString())[label["id"].toString()]=="support","classification/stale-write protection");
  QJsonObject card{{"kind","rules"},{"id","manual-card"},{"title","人工规则草稿"},{"entryRule","规则草稿完整尾部"},{"sourceRef",ref}};check(!commentWorkshop::assess(card)["complete"].toBool(),"incomplete rule not draft");card=store.put(card);
  store.put({{"kind","drafts"},{"id","rule-draft"},{"editingRuleId",card["id"]},{"editingRuleRevision",card["recordRevision"]},{"entryRule","未保存规则草稿全文"},{"sourceRef",ref}});
  CommentWorkshopStore reopened(business->filePath()+".comment-workshop.sqlite");check(reopened.get("rules","manual-card")["entryRule"]=="规则草稿完整尾部","saved card reopen lost text");const auto archive=store.archiveRule("manual-card",card["recordRevision"].toString());check(store.get("rules","manual-card").isEmpty()&&store.restoreRule(archive["id"].toString())["entryRule"]=="规则草稿完整尾部","recoverable removal/restore");rejects([&]{store.restoreRule(archive["id"].toString());});
  CommentWorkshopStore target(dir.filePath("other.sqlite"));check(target.merge(target.preview(store.backup()))["added"].toInt()==5,"full backup records missing");
  const auto missing=QJsonDocument(QJsonObject{{"webstock.commentStrategy.evidenceLabels",QJsonObject{{"1:2:absent","counter"}}}}).toJson();check(store.merge(store.preview(missing))["added"].toInt()==1,"missing old classification must remain imported");
  QJsonObject full=card;for(auto key:{"universe","timeframe","signalTiming","entryRule","exitRule","stopRule","positionRule","costRule"})full[key]="人工填写";check(commentWorkshop::assess(full)["status"]=="rule_complete_not_validated","complete rule claimed validation");
  const auto prepared=store.preview(input);staged=store.put({{"kind","previews"},{"id","import-preview"},{"preview",prepared}},store.get("previews","import-preview")["recordRevision"].toString());const auto oldStage=staged;staged=store.put({{"kind","previews"},{"id","import-preview"},{"preview",prepared}},staged["recordRevision"].toString());rejects([&]{store.merge(prepared,oldStage["recordRevision"].toString());});
  auto page=commentWorkshopPage(business);check(page->findChild<QPlainTextEdit*>("commentRule_entryRule")->toPlainText()=="未保存规则草稿全文","native draft restore failed");check(!page->findChild<QPlainTextEdit*>("commentWorkshopImportPreview")->isHidden()&&page->findChild<QPlainTextEdit*>("commentWorkshopImportPreview")->toPlainText().contains("受控观察"),"staged file preview not recovered");button(page,"重读已保存卡片（取最新）")->click();page->findChild<QPlainTextEdit*>("commentRule_stopRule")->setPlainText("人工止损草稿");button(page,"重读共享草稿")->click();check(page->findChild<QPlainTextEdit*>("commentRule_stopRule")->toPlainText()=="人工止损草稿","native draft save/read failed");button(page,"明确保存规则卡（未验证）")->click();check(page->findChild<QLabel*>("commentWorkshopState")->text().contains("已保存"),"native explicit card save failed");delete page;
  auto again=commentWorkshopPage(business);check(again->findChild<QPlainTextEdit*>("commentRule_stopRule")->toPlainText()=="人工止损草稿","native reopen lost manual rule");button(again,"打开规则的精确评论来源")->click();auto reader=again->findChild<QPlainTextEdit*>("commentRuleSourceFull");check(reader&&reader->toPlainText().contains("作者原文回复")&&reader->toPlainText().contains("完整尾部"),"actual exact-rule source reader not opened");check(commentWorkshopBack(again)&&again->findChild<QPlainTextEdit*>("commentRule_stopRule")->toPlainText()=="人工止损草稿","internal reader back lost draft");button(again,"查看分类原记录（含缺失来源）")->click();auto missingReader=again->findChild<QPlainTextEdit*>("commentClassificationSourceFull");auto readerBody=missingReader->parentWidget();readerBody->findChild<QListWidget*>()->setCurrentRow(0);check(missingReader->toPlainText().contains("缺失"),"missing classification source silently omitted");delete again;check(business->read("collections")==before,"workshop mutated business source");
  qInfo("PASS comment workshop: creator/partial/fulltext/parent/exact composite identity/import preview-merge/stale writes/rule draft-reopen/recoverable archive/backup/UI; isolated only");return 0;
}catch(const std::exception& e){qCritical()<<e.what();return 1;}}
